<?php declare(strict_types=1); require __DIR__.'/auth.php'; if(!is_file(ADMIN_FILE)){header('Location: setup.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check((string)($_POST['csrf']??'')))$err='Sicherheitsprüfung fehlgeschlagen.';elseif((int)($_SESSION['login_blocked_until']??0)>time())$err='Zu viele Versuche. Bitte warte einige Minuten.';else{$c=admin_config();$email=trim((string)($_POST['email']??''));$pw=(string)($_POST['password']??'');if(hash_equals((string)($c['email']??''),$email)&&password_verify($pw,(string)($c['password_hash']??''))){session_regenerate_id(true);$_SESSION['admin_ok']=true;$_SESSION['admin_last']=time();$_SESSION['login_attempts']=0;header('Location: index.php');exit;}$_SESSION['login_attempts']=(int)($_SESSION['login_attempts']??0)+1;if($_SESSION['login_attempts']>=5){$_SESSION['login_blocked_until']=time()+300;$_SESSION['login_attempts']=0;}$err='E-Mail oder Passwort ist nicht korrekt.';}}?><!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Admin Login</title><link rel="stylesheet" href="admin.css?v=2"><main class="box"><h1>Admin Login</h1><?php if($err):?><p class="err"><?=htmlspecialchars($err,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf(),ENT_QUOTES,'UTF-8')?>"><label>E-Mail</label><input type="email" name="email" autocomplete="username" required><label>Passwort</label><input type="password" name="password" autocomplete="current-password" required><button>Anmelden</button></form><p><a href="../index.php">← Zur Website</a></p></main></html>
